/******************************************************************************
	Report SQL
	******************************************************************************/
CREATE VIEW [FinBI].[vwSubscriptionOutstandingDebt]
AS

	SELECT 
	   TotalDebtStatus AS [Total Debt Status]
      ,[ContactNo] AS [Contact Number]
	  ,CRMParentAccount AS [CRM Parent Account]
,CRMParentAccountFirmNo AS [CRM PA Firm No]
,CRMParentAccountOfficeNo AS [CRM PA Office No]
      ,[ACCOUNTNUM] AS [AX Account No]
      ,[NAME] AS [AX Account Name]
      ,[RICCUSTINTERFACEREF] AS [CRM Account No/Contact No]
      ,[CPCompany] AS [CP Company]
      ,AD.[Salutation] AS [Salutation]
      ,[WorldRegion] AS [World Region]
      ,[ReportingWorldRegion] AS [Reporting World Region]
      ,[ReportingSubWorldRegion] AS [Reporting Sub World Region]
      ,[LocalGroup] AS [Local Group]
      ,[ReportingLocalGroup] AS [Reporting Local Group]
      ,[Country] AS [Country]
      ,[PreferredEMail] AS [Preferred EMail]
      ,[DoNotChase] AS [Do Not Chase]
,MailName As [Mail Name]
,AD.MobilePhone As [Mobile Phone]
      ,[LapsedCode] AS [Lapsed Code]
      ,[MemberGrade] AS [Member Grade]
      ,[ConcessionType] AS [Concession Type]
      ,[Region] AS [Region]
      ,[ReportingRegion] AS [Reporting Region]
      ,[PreventLapse] AS [Prevent Lapse]
      ,[AXPaymentSchedule] AS [AX Payment Schedule]
      ,[CRMPaymentCycle] AS [CRM Payment Cycle]
      ,[TRANSDATE] AS [Transaction Date]
      ,[DUEDATE] AS [Due Date]
      ,[INVOICE] AS [Invoice No]
      ,[VOUCHER] AS [Voucher]
      ,[CURRENCY] AS [Currency]
      ,[AMOUNTCUR] AS [Amount (currency)]
      ,[SETTLEAMOUNTCUR] AS [Settle Amount (Currency)]
      ,[AMOUNTMST] AS [Amount MST]
      ,[SETTLEAMOUNTMST] AS [Settle Amount MST]
      ,[BalanceCUR] AS [Balance (currency)]
      ,[BalanceGBP] AS [Balance GBP]
      ,[RDDDBucket] AS [Ageing Bucket]
      ,[RDTDBucket]
      ,[RMDDBucket]
      ,[RMTDBucket]
      ,[InvType] AS [Invoice Type]
      ,[PAYMMODE] AS [AX Payment Method]
      ,[TXT] AS [AX Text]
      ,[HITINTSYSTEMID] AS [Source System]
      ,[DaysSinceInvoiced] AS [Days Since Invoiced]
      ,[RefreshDateTime] AS [Refresh Date Time]
      ,[CostCentre] AS [Cost Centre]
      ,[RevenueStream] AS [Revenue Stream]
      ,[ProductCode] AS [Product Code]
      ,[SubsYear] AS [Subs Year]
      ,[PendingRemoval] AS [Pending Removal]
      ,[PendingRemovalDate] AS [Pending Removal Date]
      ,[Renewals] AS [Renewals]
      ,[Fulfilled] AS [Fulfilled]
      ,[LYCPDComplete] AS [LYCPD Complete]
     -- ,[LYCompletedFormalHours] AS [LY Completed Formal Hors]
      ,[CPDComplete] AS [CPD Complete]
      --,[CompletedFormalHours] AS [Completed Formal Hrs]
      ,[Payment Method] AS [Payment Method]
      ,[RICRECALREFERENCE] [RICSRECALCREFERENCE]
,ISNULL(AD.Rics_HardcopySubs,0) AS [Hardcopy Subs]
,Pathway AS [Pathway]
      ,CN.[address1_Line1] AS [Address Line1]
      ,CN.[Address1_Line2] AS [Address Line2]
      ,CN.[Address1_Line3] AS [Address Line3]
      ,CN.[Address1_City] AS [city]
      ,CN.[Address1_County] AS [County]
      ,CN.[Address1_PostalCode] AS [Postal Code]
FROM AX.tblAXAgedDebt AD
LEFT JOIN dbo.vwContact CN ON CN.Rics_contactno = AD.ContactNo
WHERE ACCOUNTNUM NOT LIKE 'ISL%'

---WHERE AD.AccountNum = 'CUK0000000'

